with q as (
 select * from (values
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-docs-05','Decreto nº 8.912/2018 — comprovação','Para comprovar as 120 horas de capacitação exigidas para promoção, qual documento o art. 19 prevê?','(A) Declaração verbal do chefe.\n(B) Certificado de curso ou evento oferecido pelo Poder Público ou por instituição de ensino credenciada pelo MEC, em área pertinente à atividade policial.\n(C) Apenas histórico escolar do ensino médio.\n(D) Recibo de inscrição em curso ainda não concluído.\n(E) Declaração do próprio servidor.','B','O art. 19 prevê certificação de cursos ou eventos oferecidos pelo Poder Público Federal, Estadual ou Municipal, ou por instituição de ensino credenciada pelo MEC, em área pertinente à atividade policial.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-annual-06','Decreto nº 8.912/2018 — avaliação anual','Como é apurada a avaliação dos fatores de promoção, conforme o art. 21?','(A) Uma única avaliação ao final da carreira.\n(B) Avaliação anual e cálculo da média ao final do triênio.\n(C) Avaliação mensal sem média.\n(D) Somente autoavaliação.\n(E) Avaliação a cada cinco anos.','B','O art. 21 determina avaliações anuais e cálculo da média ao final do triênio para verificar se o servidor atingiu o escore mínimo.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-deadline-07','Decreto nº 8.912/2018 — contagem de prazos','Segundo o art. 22, § 2º, do Decreto nº 8.912/2018, os prazos expressos em dias são contados:','(A) Apenas em dias úteis.\n(B) Em dias corridos/contínuos.\n(C) Excluindo sábados e domingos.\n(D) Somente durante o expediente.\n(E) Em semanas completas.','B','O art. 22, § 2º, determina expressamente que os prazos em dias sejam contados de modo contínuo, e não apenas em dias úteis.'),
 ('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-dec8912-annexes-08','Decreto nº 8.912/2018 — anexos de avaliação','Qual é a correspondência correta entre os anexos do Decreto nº 8.912/2018 e sua finalidade?','(A) Anexo I: bônus; Anexo II: cursos; Anexo III: quesitos.\n(B) Anexo I: quesitos; Anexo II: quadro de pontuação; Anexo III: pontuação adicional por recompensas específicas.\n(C) Todos os anexos tratam apenas de cursos.\n(D) Anexo I: recursos; Anexo II: penalidades; Anexo III: prazos.\n(E) Anexos I e II: estrutura de cargos; Anexo III: vencimentos.','B','O art. 20, § 1º, remete aos quesitos do Anexo I e ao quadro de pontuação do Anexo II. O § 2º prevê pontuação adicional do Anexo III para as recompensas indicadas no art. 96, II e III, da LC nº 129/2004.')
 ) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation)
